/* Assemble only the tools whose data source this build actually has. */

static size_t app_str(char *buf, size_t cap, size_t off, const char *s)
{
  size_t n;

  if (buf == NULL || cap == 0 || s == NULL || off >= cap - 1)
    {
      return off;
    }

  n = strlen(s);
  if (n > cap - 1 - off)
    {
      n = cap - 1 - off;
    }

  memcpy(buf + off, s, n);
  buf[off + n] = '\0';
  return off + n;
}

